import { createTopologySceneConfig, TOPOLOGY_CAMERA_BASE, TOPOLOGY_MINIMAP_BASE, TOPOLOGY_SCENE_BASE, TOPOLOGY_SIGNAL_BASE, } from "../topology/sceneConfig.js";
export function createTopologyScenePreset(options) {
    return createTopologySceneConfig({
        ...TOPOLOGY_SCENE_BASE,
        ...options,
    });
}
export function createTopologyPagePreset(options) {
    return {
        scene: createTopologyScenePreset(options.scene ?? TOPOLOGY_SCENE_BASE),
        camera: {
            ...TOPOLOGY_CAMERA_BASE,
            ...options.camera,
        },
        signal: {
            ...TOPOLOGY_SIGNAL_BASE,
            ...options.signal,
        },
        minimap: {
            ...TOPOLOGY_MINIMAP_BASE,
            ...options.minimap,
        },
    };
}
